import { ProjectDraftSectionKey } from '@prisma/client';

export const ANSWER_MAX_LENGTH = 600;
export const QUESTION_MAX_LENGTH = 300;

export interface SectionQuestionDefinition {
  key: string;
  label: string;
}

export interface SectionDefinition {
  section: ProjectDraftSectionKey;
  title: string;
  questions: SectionQuestionDefinition[];
}

/**
 * Fixed, same-for-every-edital question set per section. Deliberately not
 * generated by the AI per edital - keeps the prompt small/predictable and
 * avoids letting edital content influence what's asked of the user (one more
 * indirect prompt-injection surface avoided). See design.md.
 */
export const SECTION_DEFINITIONS: SectionDefinition[] = [
  {
    section: 'JUSTIFICATIVA',
    title: 'Justificativa',
    questions: [
      {
        key: 'problema',
        label: 'Qual problema ou necessidade o seu projeto pretende resolver?',
      },
      {
        key: 'importancia',
        label: 'Por que esse problema é importante para o público que você atende?',
      },
      {
        key: 'experiencia',
        label: 'Que experiência ou diferencial sua organização tem para executar esse projeto?',
      },
    ],
  },
  {
    section: 'OBJETIVOS',
    title: 'Objetivos',
    questions: [
      {
        key: 'objetivoPrincipal',
        label: 'Qual é o objetivo principal do projeto?',
      },
      {
        key: 'objetivosEspecificos',
        label: 'Quais são os passos ou objetivos específicos para chegar lá?',
      },
      {
        key: 'resultadoEsperado',
        label: 'Como você vai saber que o projeto deu certo?',
      },
    ],
  },
  {
    section: 'CONTRAPARTIDAS',
    title: 'Contrapartidas',
    questions: [
      {
        key: 'beneficioComunidade',
        label: 'O que o público ou a comunidade vai ganhar com esse projeto?',
      },
      {
        key: 'contrapartidaOrgao',
        label:
          'Haverá alguma contrapartida direta ao órgão financiador (ex.: divulgação, relatório, apresentação pública)?',
      },
    ],
  },
  {
    section: 'ORCAMENTO',
    title: 'Orçamento básico',
    questions: [
      {
        key: 'itensCusto',
        label: 'Quais são os principais itens de custo do projeto (ex.: material, equipe, divulgação, equipamento)?',
      },
      {
        key: 'valorTotal',
        label: 'Qual o valor total estimado do projeto?',
      },
      {
        key: 'adequacaoLimite',
        label: 'Esse valor está dentro do limite informado pelo edital? Se não, como pretende complementar?',
      },
    ],
  },
];

export function getSectionDefinition(section: ProjectDraftSectionKey): SectionDefinition {
  const definition = SECTION_DEFINITIONS.find((s) => s.section === section);
  if (!definition) {
    throw new Error(`No question definition for section "${section}"`);
  }
  return definition;
}
